func encQuestion(out []byte, v *Question, depth int) []byte {
	out = append(out, '{')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "asker")
	out = append(out, ':', ' ')
	out = esc(out, v.Asker)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "key")
	out = append(out, ':', ' ')
	out = esc(out, v.Key)
	if len(v.Slots) != 0 {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "slots")
		out = append(out, ':', ' ')
		out = strmap(out, v.Slots, depth+1)
	}
	out = append(out, '\n')
	out = pad(out, depth)
	return append(out, '}')
}

