func encResponseMetadata(out []byte, v *ResponseMetadata, depth int) []byte {
	out = append(out, '{')
	first := true
	if v.Code != "" {
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "code")
		out = append(out, ':', ' ')
		out = esc(out, v.Code)
	}
	if v.Error != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "error")
		out = append(out, ':', ' ')
		out = esc(out, v.Error)
	}
	if v.Answer != nil {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "answer")
		out = append(out, ':', ' ')
		out = encAnswer(out, v.Answer, depth+1)
	}
	if len(v.Records) != 0 {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "records")
		out = append(out, ':', ' ')
		out = encList(out, v.Records, depth+1, encRecordMetadata)
	}
	if !first {
		out = append(out, '\n')
		out = pad(out, depth)
	}
	return append(out, '}')
}

